}

"use client";

import { cn } from "@/lib/utils";
import {
  CheckCheck,
  Menu,
  MessageCircle,
  Mic,
  MoreVertical,
  Paperclip,
  Phone,
  Search,
  Send,
  Video,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";

// ==========================================
// VARIANT & COLOR CONFIGURATION
// ==========================================
export type ChatVariant = "default" | "minimal" | "glass" | "liquid-glass";

// Added (string & {}) so it accepts arbitrary hex codes without losing IDE autocomplete for the presets
export type ChatColor = "indigo" | "rose" | "emerald" | "zinc" | (string & {});

export function LiquidGlassSvgFilter() {
  return (
    <>
      <img
        src="https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_1200,c_limit/v1790146209/photo-1470071459604-3b5ec3a7fe05-1790146212205.jpg"
        alt=""
        aria-hidden="true"
        style={{
          position: "fixed",
          top: "-9999px",
          left: "-9999px",
          width: "1px",
          height: "1px",
          opacity: 0,
          pointerEvents: "none",
        }}
      />
      <svg
        style={{
          position: "fixed",
          top: "-9999px",
          left: "-9999px",
          width: 0,
          height: 0,
          pointerEvents: "none",
        }}
        aria-hidden="true"
      >
        <defs>
          <filter
            id="glass-blur"
            x="0"
            y="0"
            width="100%"
            height="100%"
            filterUnits="objectBoundingBox"
          >
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.003 0.007"
              numOctaves="1"
              result="turbulence"
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="turbulence"
              scale="200"
              xChannelSelector="R"
              yChannelSelector="G"
            />
          </filter>
        </defs>
      </svg>
    </>
  );
}

const chatVariants: Record<ChatVariant, Record<string, string>> = {
  default: {
    wrapper:
      "bg-background border border-border rounded-2xl",
    sidebar:
