/** One bubble in a conversation. */
export type ChatMessage = {
  id: string | number;
  text: string;
  sender: "me" | "them";
  time: string;
  /** Only meaningful on your own messages. */
  status?: "delivered" | "read";
};

export type Contact = {
  id: string | number;
  name: string;
  message: string;
  date: string;
  unread: number;
  status: "online" | "offline" | (string & {});
  avatar?: string;
  initials?: string;
  color?: string;
};

export type CurrentUser = {
  avatar: string;
  status: "online" | "offline" | (string & {});
  name?: string;
};

const BulletproofAvatar = ({
  src,
  initials,
  color,
  status,
  size = 40,
  statusBorder = "border-background",
}: {
  src?: string;
  initials?: string;
  color?: string;
  status?: string;
  size?: number;
  statusBorder?: string;
}) => (
  <div
    className="relative shrink-0 flex-none rounded-full"
    style={{ width: size, height: size, minWidth: size, minHeight: size }}
  >
    <div className="w-full h-full rounded-full overflow-hidden bg-muted flex items-center justify-center shadow-sm">
      {src ? (
        <img
          src={src}
          alt="Avatar"
          className="w-full h-full object-cover block m-0 p-0"
        />
      ) : (
        <div
          className={`w-full h-full flex items-center justify-center font-semibold text-sm m-0 p-0 tracking-wider ${color}`}
        >
          {initials}
        </div>
      )}
    </div>
    {status && (
      <span
        className={`absolute bottom-0 right-0 w-3 h-3 rounded-full border-2 z-10 m-0 p-0 ${statusBorder} ${status === "online" ? "bg-emerald-500" : status === "offline" ? "bg-muted-foreground" : "bg-rose-500"}`}
      />
    )}
  </div>
);

export default function ChatApp({
  currentUser,
  contactsData,
  variant = "default",
  color = "primary",
}: {
  currentUser: CurrentUser;
  contactsData: Contact[];
  variant?: ChatVariant;
  color?: ChatColor;
}) {
  // Custom hex injection logic
  const isCustomHex = color?.startsWith("#");
  const customVars = isCustomHex
    ? ({
        "--chat-custom": color,
        "--chat-custom-10": `${color}1a`,
        "--chat-custom-20": `${color}33`,
        "--chat-custom-50": `${color}80`,
      } as React.CSSProperties)
    : {};

  const theme = isCustomHex
    ? {
        text: "text-[var(--chat-custom)]",
        bg: "bg-[var(--chat-custom)] hover:brightness-110 text-white",
        lightBg: "bg-[var(--chat-custom-10)] text-[var(--chat-custom)]",
        gradient: "from-[var(--chat-custom)] to-[var(--chat-custom-50)]",
        shadow: "shadow-[0_4px_14px_0_var(--chat-custom-20)]",
        focusRing:
          "focus-within:border-[var(--chat-custom-50)] focus-within:ring-2 focus-within:ring-[var(--chat-custom-20)]",
      }
    : colorThemes[color] || colorThemes["primary"];

  const styles = chatVariants[variant];

  // Text sitting on the accent colour. Read it off `theme.bg` instead of
  // assuming white: `primary` is near-black in light mode and near-white in
  // dark, so a hardcoded white disappears on one side or the other.
  const onAccentText =
    theme.bg
      .split(" ")
      .filter((c) => c.startsWith("text-") || c.startsWith("dark:text-"))
      .join(" ") || "text-primary-foreground";

  const [searchQuery, setSearchQuery] = useState("");
  const [activeContact, setActiveContact] = useState<Contact | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [filterType, setFilterType] = useState<"all" | "online">("all");

  const [contacts, setContacts] = useState(contactsData);
  const [inputValue, setInputValue] = useState("");
  const [isTyping, setIsTyping] = useState<string | number | null>(null);

  const chatScrollRef = useRef<HTMLDivElement>(null);

  const [chatHistories, setChatHistories] = useState<Record<string, ChatMessage[]>>(
    () => {
      const initialChats: Record<string, ChatMessage[]> = {};
      contactsData.forEach((contact) => {
        initialChats[contact.id] = [
          {
            id: `initial-${contact.id}`,
            text: contact.message,
            sender: "them",
            time: contact.date,
            status: "read",
          },
        ];
      });
      return initialChats;
    },
  );

  useEffect(() => {
    if (chatScrollRef.current) {
      chatScrollRef.current.scrollTop = chatScrollRef.current.scrollHeight;
    }
  }, [chatHistories, activeContact, isTyping]);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 640) {
        setIsSidebarOpen(true);
      }
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const filteredContacts = contacts.filter((contact) => {
    const matchesSearch = contact.name
      .toLowerCase()
      .includes(searchQuery.toLowerCase());
    const matchesFilter = filterType === "all" || contact.status === "online";
    return matchesSearch && matchesFilter;
  });

  const handleSendMessage = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputValue.trim() || !activeContact) return;

    const currentTime = new Date().toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    });
    const newUserMsg: ChatMessage = {
      id: Date.now(),
      text: inputValue,
      sender: "me",
      time: currentTime,
      status: "delivered",
    };

    setChatHistories((prev) => ({
      ...prev,
      [activeContact.id]: [...(prev[activeContact.id] || []), newUserMsg],
    }));
    setContacts((prev) =>
      prev.map((c) =>
        c.id === activeContact.id
          ? { ...c, message: inputValue, date: currentTime }
          : c,
      ),
    );
    setInputValue("");
    setIsTyping(activeContact.id);

    setTimeout(() => {
      setIsTyping(null);
      const replyTime = new Date().toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      });
      const replyMsg: ChatMessage = {
        id: Date.now() + 1,
        text: "That sounds perfect! Let's get it done. 🚀",
        sender: "them",
        time: replyTime,
        status: "read",
      };

      setChatHistories((prev) => {
        const updatedHistory = [...(prev[activeContact.id] || [])];
        const lastMsg = updatedHistory[updatedHistory.length - 1];
        if (lastMsg.sender === "me") lastMsg.status = "read";
        return { ...prev, [activeContact.id]: [...updatedHistory, replyMsg] };
      });

      setContacts((prev) =>
        prev.map((c) =>
          c.id === activeContact.id
            ? { ...c, message: replyMsg.text, date: replyTime, unread: 0 }
            : c,
        ),
      );
    }, 2000);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleContactClick = (contact: Contact) => {
    setActiveContact(contact);
    setContacts((prev) =>
      prev.map((c) => (c.id === contact.id ? { ...c, unread: 0 } : c)),
    );
    if (typeof window !== "undefined" && window.innerWidth < 640)
      setIsSidebarOpen(false);
  };

  return (
    <div
      style={customVars}
      className={cn(
        "w-full max-w-full h-[750px] flex overflow-hidden relative font-sans box-border transition-colors duration-300 isolate [contain:paint] [transform:translateZ(0)]",
        styles.wrapper,
      )}
    >
      <LiquidGlassSvgFilter />
      {variant === "liquid-glass" && (
        <>
          {/* Inner Clipping Container for Liquid Background Stack */}
          <div className="absolute inset-0 overflow-hidden rounded-[22px] sm:rounded-[28px] pointer-events-none z-0">
            {/* Layer 0: Liquid SVG Displaced Wave Background */}
            <div
              className="absolute -inset-10"
              style={{
                backgroundImage:
                  'url("https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_1200,c_limit/v1790146209/photo-1470071459604-3b5ec3a7fe05-1790146212205.jpg")',
                backgroundSize: "cover",
                backgroundPosition: "center",
                filter: "url(#glass-blur)",
                transform: "scale(1.1)",
              }}
            />

            {/* Layer 1: Contrast overlay & soft backdrop blur */}
            <div className="absolute inset-0 bg-black/30 dark:bg-black/45 backdrop-blur-[2px]" />

            {/* Layer 2: Ambient Drop Shadow & Subtle Glow */}
            <div
              className="absolute inset-0 rounded-[22px] sm:rounded-[28px]"
              style={{
                boxShadow:
                  "0 20px 50px rgba(0, 0, 0, 0.4), 0 0 20px rgba(255, 255, 255, 0.08)",
              }}
            />
          </div>

          {/* Layer 3: Specular Inner Border Highlight */}
          <div
            className="absolute inset-0 z-40 pointer-events-none rounded-[22px] sm:rounded-[28px] border border-white/40 dark:border-white/15"
            style={{
              boxShadow:
                "inset 2px 2px 2px 0 rgba(255, 255, 255, 0.45), inset -2px -2px 2px 0 rgba(255, 255, 255, 0.3)",
            }}
          />
        </>
      )}

      {/* === LEFT SIDEBAR === */}
      <aside
        className={cn(
          `absolute sm:relative z-30 w-[300px] sm:w-80 h-full shrink-0 flex-none flex flex-col transition-transform duration-300 ease-in-out overflow-hidden ${isSidebarOpen ? "translate-x-0" : "-translate-x-full sm:translate-x-0"}`,
          styles.sidebar,
          variant === "liquid-glass" && "rounded-l-[22px] sm:rounded-l-[28px] max-sm:rounded-r-2xl max-sm:border-r max-sm:border-white/20",
          variant === "glass" && "max-sm:rounded-r-2xl max-sm:bg-white/80 max-sm:dark:bg-black/60 max-sm:backdrop-blur-2xl max-sm:shadow-2xl",
          variant === "default" && "max-sm:rounded-r-2xl max-sm:shadow-2xl",
        )}
      >
        {variant === "liquid-glass" && (
          <div className="absolute inset-0 pointer-events-none z-0 overflow-hidden">
            {/* Liquid SVG Displaced Wave Background in Sidebar */}
            <div
              className="absolute -inset-10"
              style={{
                backgroundImage:
                  'url("https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_1200,c_limit/v1790146209/photo-1470071459604-3b5ec3a7fe05-1790146212205.jpg")',
                backgroundSize: "cover",
                backgroundPosition: "left center",
                filter: "url(#glass-blur)",
                transform: "scale(1.1)",
              }}
            />
            <div className="absolute inset-0 bg-black/35 dark:bg-black/50 backdrop-blur-[2px]" />
          </div>
        )}

        <div className="relative z-10 flex flex-col h-full">
          <div className="pt-6 pb-4 px-5 shrink-0 flex-none min-w-0 box-border">
            <div className="flex items-center justify-between mb-6">
              <h1 className={cn(
                "text-xl font-semibold tracking-tight",
                variant === "liquid-glass" ? "text-white" : "text-foreground"
              )}>
                Messages
              </h1>
              <BulletproofAvatar
                src={currentUser.avatar}
                status={currentUser.status}
                size={36}
                statusBorder={
                  variant === "liquid-glass" || variant === "glass"
                    ? "border-transparent"
                    : "border-card"
                }
              />
            </div>

            <div className="relative w-full min-w-0 mb-4 group">
              <Search className={cn(
                "w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 shrink-0 transition-colors",
                variant === "liquid-glass" ? "text-white/60 group-focus-within:text-white" : "text-muted-foreground group-focus-within:text-muted-foreground"
              )} />
              <input
                type="text"
                placeholder="Search..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className={cn(
                  "w-full min-w-0 rounded-xl py-2 pl-10 pr-4 text-sm outline-none text-foreground transition-all placeholder:text-muted-foreground",
                  styles.inputBg,
                  theme.focusRing,
                )}
              />
            </div>

            <div
              className={cn(
                "flex gap-1 p-1 rounded-lg",
                variant === "liquid-glass"
                  ? "bg-white/15 dark:bg-black/30 border border-white/20 dark:border-white/10"
                  : variant === "glass"
                    ? "bg-black/20"
                    : "bg-muted/80",
              )}
            >
              <button
                onClick={() => setFilterType("all")}
                className={cn(
                  "flex-1 py-1.5 text-xs font-semibold rounded-md transition-all cursor-pointer",
                  filterType === "all"
                    ? variant === "liquid-glass"
                      ? "bg-white text-zinc-900 font-semibold shadow-sm"
                      : "bg-card text-foreground shadow-sm"
                    : variant === "liquid-glass"
                      ? "text-white/70 hover:text-white"
                      : "text-muted-foreground hover:text-foreground"
                )}
              >
                All
              </button>
              <button
                onClick={() => setFilterType("online")}
                className={cn(
                  "flex-1 py-1.5 text-xs font-semibold rounded-md transition-all cursor-pointer",
                  filterType === "online"
                    ? variant === "liquid-glass"
                      ? "bg-white text-zinc-900 font-semibold shadow-sm"
                      : "bg-card text-foreground shadow-sm"
                    : variant === "liquid-glass"
                      ? "text-white/70 hover:text-white"
                      : "text-muted-foreground hover:text-foreground"
                )}
              >
                Online
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto px-2 pb-4 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
            {filteredContacts.length > 0 ? (
              filteredContacts.map((contact) => (
                <div
                  key={contact.id}
                  onClick={() => handleContactClick(contact)}
                  className={cn(
                    "px-3 py-2 flex items-center gap-3 cursor-pointer transition-all rounded-xl",
                    activeContact?.id === contact.id
                      ? variant === "liquid-glass"
                        ? "bg-white text-zinc-900 font-semibold shadow-md"
                        : theme.lightBg
                      : variant === "liquid-glass"
                        ? "hover:bg-white/10 text-white/80"
                        : "hover:bg-muted/80"
                  )}
                >
                  <BulletproofAvatar
                    src={contact.avatar}
                    initials={contact.initials}
                    color={contact.color}
                    status={contact.status}
                    size={44}
                    statusBorder={
                      activeContact?.id === contact.id
                        ? "border-transparent"
                        : variant === "liquid-glass" || variant === "glass"
                          ? "border-transparent"
                          : "border-card"
                    }
                  />
                  <div className="flex-1 min-w-0 overflow-hidden flex flex-col justify-center">
                    <div className="flex justify-between items-baseline mb-1 gap-2">
                      <h4
                        className={cn(
                          "text-sm mb-0 font-semibold truncate",
                          activeContact?.id === contact.id
                            ? variant === "liquid-glass"
                              ? "text-zinc-900"
                              : theme.text
                            : variant === "liquid-glass"
                              ? "text-white"
                              : "text-foreground"
                        )}
                      >
                        {contact.name}
                      </h4>
                      <span
                        className={cn(
                          "text-[10px] font-medium shrink-0",
                          activeContact?.id === contact.id
                            ? variant === "liquid-glass"
                              ? "text-zinc-700 font-semibold"
                              : theme.text
                            : variant === "liquid-glass"
                              ? "text-white/60"
                              : "text-muted-foreground"
                        )}
                      >
                        {contact.date}
                      </span>
                    </div>
                    <div className="flex justify-between items-center gap-2">
                      <p
                        className={cn(
                          "text-xs mt-0 truncate",
                          activeContact?.id === contact.id
                            ? variant === "liquid-glass"
                              ? "text-zinc-700 font-medium"
                              : theme.text
                            : variant === "liquid-glass"
                              ? "text-white/70"
                              : "text-muted-foreground opacity-80"
                        )}
                      >
                        {contact.message}
                      </p>
                      {contact.unread > 0 && (
                        <span
                          className={cn(
                            "w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-semibold shrink-0 shadow-sm",
                            activeContact?.id === contact.id && variant === "liquid-glass"
                              ? "bg-zinc-900 text-white"
                              : cn("text-white", theme.bg)
                          )}
                        >
                          {contact.unread}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className={cn(
                "p-8 text-center text-sm flex flex-col items-center gap-2",
                variant === "liquid-glass" ? "text-white/60" : "text-muted-foreground"
              )}>
                <MessageCircle className="w-8 h-8 opacity-40" /> No contacts found
              </div>
            )}
          </div>
        </div>
      </aside>

      {isSidebarOpen && (
        <div
          className={cn(
            "absolute inset-0 z-20 sm:hidden cursor-pointer rounded-[inherit] overflow-hidden",
            variant === "liquid-glass"
              ? "bg-black/25 backdrop-blur-[2px]"
              : variant === "glass"
                ? "bg-black/30 backdrop-blur-sm"
                : "bg-black/40 dark:bg-black/60 backdrop-blur-sm",
          )}
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* === MAIN CHAT AREA === */}
      <main
        className={cn(
          "flex-1 flex flex-col min-w-0 w-full h-full relative z-10 transition-colors duration-300",
          styles.main,
        )}
      >
        {!activeContact ? (
          <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
            <div
              className={cn(
                "w-24 h-24 rounded-3xl flex items-center justify-center mb-6 rotate-3 shrink-0 flex-none shadow-xl",
                variant === "liquid-glass"
                  ? "border bg-white/20 border-white/30 text-white backdrop-blur-md shadow-2xl"
                  : cn("bg-gradient-to-tr border border-border", theme.gradient, theme.shadow, onAccentText),
              )}
            >
              <MessageCircle className="w-10 h-10 -rotate-3" />
            </div>
            <h3 className={cn(
              "text-xl font-semibold mb-2",
              variant === "liquid-glass" ? "text-white" : "text-foreground"
            )}>
              Your Messages
            </h3>
            <p className={cn(
              "text-sm max-w-xs",
              variant === "liquid-glass" ? "text-white/70" : "text-muted-foreground"
            )}>
              Select a conversation from the sidebar or start a new one to begin
              chatting.
            </p>
            <button
              className={cn(
                "mt-8 px-6 py-2.5 rounded-full text-sm font-semibold sm:hidden transition-transform active:scale-95 shadow-lg cursor-pointer",
                theme.bg,
                theme.shadow,
              )}
              onClick={() => setIsSidebarOpen(true)}
            >
              Open Contacts
            </button>
          </div>
        ) : (
          <>
            <header
              className={cn(
                "h-[76px] px-4 sm:px-6 flex justify-between items-center shrink-0 flex-none min-w-0 w-full box-border z-10 transition-colors duration-300",
                styles.header,
              )}
            >
              <div className="flex items-center gap-3 sm:gap-4 min-w-0">
                <button
                  className={cn(
                    "sm:hidden p-2 -ml-2 shrink-0 flex-none cursor-pointer",
                    variant === "liquid-glass" ? "text-white/80 hover:text-white" : "text-muted-foreground hover:text-foreground"
                  )}
                  onClick={() => setIsSidebarOpen(true)}
                >
                  <Menu className="w-5 h-5" />
                </button>
                <BulletproofAvatar
                  src={activeContact.avatar}
                  initials={activeContact.initials}
                  color={activeContact.color}
                  status={activeContact.status}
                  size={42}
                  statusBorder={
                    variant === "liquid-glass" || variant === "glass"
                      ? "border-transparent"
                      : "border-background"
                  }
                />
                <div className="min-w-0 flex-1">
                  <h2 className={cn(
                    "text-base font-semibold leading-tight truncate",
                    variant === "liquid-glass" ? "text-white" : "text-foreground"
                  )}>
                    {activeContact.name}
                  </h2>
                  <div className="flex items-center gap-1.5 mt-0.5">
                    <span
                      className={`w-1.5 h-1.5 rounded-full ${activeContact.status === "online" ? "bg-emerald-500" : "bg-muted-foreground"}`}
                    />
                    <p className={cn(
                      "text-xs font-medium capitalize truncate",
                      variant === "liquid-glass" ? "text-white/70" : "text-muted-foreground"
                    )}>
                      {isTyping === activeContact.id ? (
                        <span className={cn("animate-pulse", theme.text)}>
                          Typing...
                        </span>
                      ) : (
                        activeContact.status
                      )}
                    </p>
                  </div>
                </div>
              </div>
              <div className={cn(
                "flex items-center gap-1 sm:gap-2 shrink-0 flex-none ml-2",
                variant === "liquid-glass" ? "text-white/80" : "text-muted-foreground"
              )}>
                <button className={cn(
                  "p-2 rounded-full transition-colors hidden sm:block cursor-pointer",
                  variant === "liquid-glass" ? "hover:bg-white/10 hover:text-white" : "hover:bg-muted"
                )}>
                  <Phone className="w-4 h-4" />
                </button>
                <button className={cn(
                  "p-2 rounded-full transition-colors hidden sm:block cursor-pointer",
                  variant === "liquid-glass" ? "hover:bg-white/10 hover:text-white" : "hover:bg-muted"
                )}>
                  <Video className="w-4 h-4" />
                </button>
                <button className={cn(
                  "p-2 rounded-full transition-colors cursor-pointer",
                  variant === "liquid-glass" ? "hover:bg-white/10 hover:text-white" : "hover:bg-muted"
                )}>
                  <MoreVertical className="w-4 h-4" />
                </button>
              </div>
            </header>

            <div
              ref={chatScrollRef}
              className="flex-1 p-4 sm:p-6 overflow-y-auto overflow-x-hidden w-full scroll-smooth"
            >
              <div className="flex flex-col gap-6 w-full pb-2">
                {chatHistories[activeContact.id]?.map((msg) => {
                  const isMe = msg.sender === "me";
                  return (
                    <div
                      key={msg.id}
                      className={`flex items-end gap-2.5 w-full ${isMe ? "justify-end" : "justify-start"}`}
                    >
                      {!isMe && (
                        <BulletproofAvatar
                          src={activeContact.avatar}
                          initials={activeContact.initials}
                          color={activeContact.color}
                          size={28}
                        />
                      )}
                      <div
                        className={`flex flex-col gap-1 max-w-[85%] sm:max-w-[70%] ${isMe ? "items-end" : "items-start"}`}
                      >
                        <div
                          className={cn(
                            "px-4 py-2.5",
                            isMe
                              ? cn(
                                  styles.msgMe,
                                  "bg-gradient-to-br",
                                  theme.gradient,
                                  onAccentText,
                                )
                              : styles.msgThem,
                          )}
                        >
                          <p className="text-[14px] whitespace-pre-wrap break-words leading-relaxed">
                            {msg.text}
                          </p>
                        </div>
                        <div
                          className={`flex items-center gap-1.5 px-1 ${isMe ? "flex-row-reverse" : "flex-row"}`}
                        >
                          <span className={cn(
                            "text-[10px] font-medium",
                            variant === "liquid-glass" ? "text-white/60" : "text-muted-foreground"
                          )}>
                            {msg.time}
                          </span>
                          {isMe && (
                            <CheckCheck
                              className={cn(
                                "w-3.5 h-3.5",
                                msg.status === "read"
                                  ? theme.text
                                  : variant === "liquid-glass" ? "text-white/50" : "text-muted-foreground/50",
                              )}
                            />
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}

                {isTyping === activeContact.id && (
                  <div className="flex items-end gap-2.5 w-full justify-start animate-in fade-in slide-in-from-bottom-2 duration-300">
                    <BulletproofAvatar
                      src={activeContact.avatar}
                      initials={activeContact.initials}
                      color={activeContact.color}
                      size={28}
                    />
                    <div
                      className={cn(
                        "px-4 py-3.5 flex items-center gap-1.5",
                        styles.msgThem,
                      )}
                    >
                      <span className={cn(
                        "w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s]",
                        variant === "liquid-glass" ? "bg-white/60" : "bg-muted-foreground"
                      )} />
                      <span className={cn(
                        "w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s]",
                        variant === "liquid-glass" ? "bg-white/60" : "bg-muted-foreground"
                      )} />
                      <span className={cn(
                        "w-1.5 h-1.5 rounded-full animate-bounce",
                        variant === "liquid-glass" ? "bg-white/60" : "bg-muted-foreground"
                      )} />
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div
              className={cn(
                "p-3 sm:p-4 shrink-0 flex-none w-full box-border z-10 transition-colors duration-300",
                styles.footer,
              )}
            >
              <form
                onSubmit={handleSendMessage}
                className={cn(
                  "flex items-center gap-2 sm:gap-3 w-full rounded-full transition-all px-4 py-1.5",
                  styles.inputBg,
                  styles.composer,
                  theme.focusRing,
                )}
              >
                <button
                  type="button"
                  className={cn(
                    "p-1.5 -ml-1.5 transition-colors shrink-0 cursor-pointer",
                    variant === "liquid-glass" ? "text-white/70 hover:text-white" : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  <Paperclip className="w-5 h-5" />
                </button>
                <input
                  type="text"
                  placeholder="Message..."
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  onKeyDown={handleKeyDown}
                  className={cn(
                    "flex-1 min-w-0 w-full bg-transparent border-none focus:outline-none text-[15px] text-foreground py-1.5",
                    variant === "liquid-glass" ? "placeholder:text-white/40" : "placeholder:text-muted-foreground"
                  )}
                />
                <button
                  type="button"
                  className={cn(
                    "p-1.5 transition-colors shrink-0 mr-1 cursor-pointer",
                    variant === "liquid-glass" ? "text-white/70 hover:text-white" : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  <Mic className="w-4 h-4" />
                </button>
                <button
                  type="submit"
                  disabled={!inputValue.trim()}
                  className={cn(
                    "w-10 h-10 rounded-full flex items-center justify-center shrink-0 flex-none hover:scale-105 active:scale-95 disabled:opacity-50 disabled:hover:scale-100 disabled:shadow-none transition-all cursor-pointer shadow-md",
                    theme.bg,
                    theme.shadow,
                  )}
                >
                  <Send className="w-4 h-4 ml-0.5 text-white" />
                </button>
              </form>
            </div>
          </>
        )}
      </main>
    </div>
  );
}
